import type { TranslationsMap } from '@/lib/i18n-page';
const t: TranslationsMap = {
  en: { title: "For NGOs — Instituto Brasil Te Ama", description: "Your NGO can receive support from the Brasil Te Ama network. Organizations working in areas of social vulnerability can register — with clear criteria, accountability, and respect for autonomy.", html: "<section class=\"subhero\"><div class=\"container\"><div class=\"subhero__inner fade-up\"><span class=\"eyebrow eyebrow--bordo\">For institutional NGOs</span><h1 class=\"subhero__title\"> Your NGO can go further —<br> with a network that <em>is already in motion.</em></h1><p class=\"subhero__sub\"> Instituto Brasil Te Ama connects verified humanitarian organizations to a structured support network — with credentials from the Sovereign Order of the Knights of Malta OSJ, partner companies, and transparency at every step.</p><div style=\"margin-top: 28px; display: flex; gap: 14px; flex-wrap: wrap;\"> <a href=\"#formulario\" class=\"btn btn--primary\">Register my NGO →</a> <a href=\"#criterios\" class=\"btn btn--secondary\">Understand the criteria ↓</a></div></div></div></section>\r\n\r\n<!-- O QUE OFERECEMOS --><section class=\"section section--white\"><div class=\"container\"><div class=\"section-header fade-up\"> <span class=\"eyebrow\">What we offer</span><h2 class=\"section-title\"> What the Institute offers<br> for NGOs.</h2><hr class=\"divider\"><p class=\"section-sub\" style=\"margin-top: 18px;\"> This is not a one-off donation. It&#39;s not about campaign visibility. It&#39;s a long-term partnership — with clear criteria, a transparent process, and mutual commitment. </p></div><div class=\"grid\" style=\"grid-template-columns: repeat(3, 1fr); gap: 20px;\"><article class=\"card fade-up delay-1\"><div class=\"card__body\" style=\"padding: 28px;\"><div style=\"width:42px; height:42px; border-radius: 10px; background: var(--blush); display: inline-flex; align-items: center; justify-content: center; color: var(--bordo); margin-bottom: 14px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 18px; line-height: 1.3; margin-bottom: 10px;\"> Financial or structural support</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> Resources generated by the Selo Brasil Te Ama Program are directed to registered NGOs — in the form of financial aid or supplies. </p></div></article><article class=\"card fade-up delay-2\"><div class=\"card__body\" style=\"padding: 28px;\"><div style=\"width:42px; height:42px; border-radius: 10px; background: var(--blush); display: inline-flex; align-items: center; justify-content: center; color: var(--bordo); margin-bottom: 14px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 18px; line-height: 1.3; margin-bottom: 10px;\"> Institutional visibility</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> Supported NGOs are mentioned in the Institute&#39;s public communications — on the website, reports, and promotional materials — with discretion and respect. </p></div></article><article class=\"card fade-up delay-3\"><div class=\"card__body\" style=\"padding: 28px;\"><div style=\"width:42px; height:42px; border-radius: 10px; background: var(--blush); display: inline-flex; align-items: center; justify-content: center; color: var(--bordo); margin-bottom: 14px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 18px; line-height: 1.3; margin-bottom: 10px;\"> Partnership endorsement</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> The association with Instituto Brasil Te Ama and the Sovereign Order of the Knights of Malta OSJ confers additional credibility with donors, partners and public bodies. </p></div></article><article class=\"card fade-up delay-4\"><div class=\"card__body\" style=\"padding: 28px;\"><div style=\"width:42px; height:42px; border-radius: 10px; background: var(--blush); display: inline-flex; align-items: center; justify-content: center; color: var(--bordo); margin-bottom: 14px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 18px; line-height: 1.3; margin-bottom: 10px;\"> Structured and ongoing support</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> This is not an isolated action. It is a flow of support generated by the Institute&#39;s partner companies. </p></div></article><article class=\"card fade-up delay-1\"><div class=\"card__body\" style=\"padding: 28px;\"><div style=\"width:42px; height:42px; border-radius: 10px; background: var(--blush); display: inline-flex; align-items: center; justify-content: center; color: var(--bordo); margin-bottom: 14px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 18px; line-height: 1.3; margin-bottom: 10px;\"> Transparency at every step.</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> The Institute documents the destination of each grant. Your organization knows what it receives, when it comes from, and where it comes from. </p></div></article><article class=\"card fade-up delay-2\"><div class=\"card__body\" style=\"padding: 28px;\"><div style=\"width:42px; height:42px; border-radius: 10px; background: var(--blush); display: inline-flex; align-items: center; justify-content: center; color: var(--bordo); margin-bottom: 14px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 18px; line-height: 1.3; margin-bottom: 10px;\"> Autonomy preserved</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> The partnership is limited to the agreed-upon support. The Institute does not interfere in the management or internal decisions of the NGO.</p></div></article></div></div></section>\r\n\r\n<!-- COMO FUNCIONA O PROCESSO --><section class=\"section section--alt\" id=\"processo\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">How it works</span><h2 class=\"section-title\"> How does the process work?<br> selection of NGOs. </h2><hr class=\"divider divider--center\"></div><div class=\"steps\"><article class=\"step fade-up delay-1\"><div class=\"step__num\"> 01</div><h3 class=\"step__title\"> Register</h3><p class=\"step__desc\"> Your NGO fills out the form with institutional data, area of activity, and a description of its work. No documents are required at this stage.</p></article><article class=\"step fade-up delay-2\"><div class=\"step__num\"> 02</div><h3 class=\"step__title\"> Institutional analysis</h3><p class=\"step__desc\"> The Institute evaluates the registration based on public criteria. The analysis is conducted by the internal team within 15 business days.</p></article><article class=\"step fade-up delay-3\"><div class=\"step__num\"> 03</div><h3 class=\"step__title\"> Alignment</h3><p class=\"step__desc\"> Meeting to align terms, areas of focus, and expectations. Unapproved NGOs receive feedback with guidance when possible.</p></article><article class=\"step fade-up delay-4\"><div class=\"step__num\"> 04</div><h3 class=\"step__title\"> Active partnership</h3><p class=\"step__desc\"> The NGO will now be part of the network and will receive structured support, with a signed partnership agreement and periodic monitoring.</p></article></div></div></section>\r\n\r\n<!-- CRITÉRIOS --><section class=\"section section--white\" id=\"criterios\"><div class=\"container\"><div class=\"section-header fade-up\"> <span class=\"eyebrow\">Eligibility</span><h2 class=\"section-title\"> What are the criteria?<br> selection.</h2><hr class=\"divider\"><p class=\"section-sub\" style=\"margin-top: 18px;\"> Clear criteria protect the integrity of the network — for partner companies, for the public, and for the organizations that comprise it. </p></div><div class=\"grid\" style=\"grid-template-columns: 1fr 1fr 1fr; gap: 16px;\"><article class=\"card fade-up delay-1\" style=\"padding: 0;\"><div style=\"padding: 18px 24px; background: var(--blush); border-bottom: 1px solid var(--border);\"><p style=\"font-size: 11px; font-weight: 700; letter-spacing: 2.5px; color: var(--bordo); text-transform: uppercase;\"> Mandatory criteria </p></div><ul style=\"list-style: none; padding: 22px 24px; display: flex; flex-direction: column; gap: 12px;\"><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polyline points=\"20 6 9 17 4 12\"/></svg> Active and regular CNPJ (Brazilian company tax ID), with no serious registration restrictions. </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polyline points=\"20 6 9 17 4 12\"/></svg> Proven experience in an area compatible with the Institute&#39;s values. </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polyline points=\"20 6 9 17 4 12\"/></svg> Absence of a public history of serious irregularities or misappropriation of funds. </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polyline points=\"20 6 9 17 4 12\"/></svg> Opening for accountability to the Institute </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polyline points=\"20 6 9 17 4 12\"/></svg> Ability to receive support and apply it in a verifiable way. </li></ul></article><article class=\"card fade-up delay-2\" style=\"padding: 0;\"><div style=\"padding: 18px 24px; background: rgba(183,154,99,.12); border-bottom: 1px solid var(--border);\"><p style=\"font-size: 11px; font-weight: 700; letter-spacing: 2.5px; color: var(--dourado); text-transform: uppercase;\"> They increase the priority. </p></div><ul style=\"list-style: none; padding: 22px 24px; display: flex; flex-direction: column; gap: 12px;\"><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--dourado)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polygon points=\"12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2\"/></svg> Consistent track record and significant length of existence. </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--dourado)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polygon points=\"12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2\"/></svg> Verifiable public presence — website, social media, or reports. </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--dourado)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polygon points=\"12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2\"/></svg> Strategic geographic coverage or complementary coverage to already supported NGOs. </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--dourado)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polygon points=\"12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2\"/></svg> Thematic alignment with the Institute&#39;s priority areas. </li></ul></article><article class=\"card fade-up delay-3\" style=\"padding: 0;\"><div style=\"padding: 18px 24px; background: rgba(0,0,0,.04); border-bottom: 1px solid var(--border);\"><p style=\"font-size: 11px; font-weight: 700; letter-spacing: 2.5px; color: var(--grafite); text-transform: uppercase;\"> They prevent approval. </p></div><ul style=\"list-style: none; padding: 22px 24px; display: flex; flex-direction: column; gap: 12px;\"><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--grafite)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg> Inactive CNPJ or CNPJ with serious unresolved irregularity. </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--grafite)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg> History of misappropriation of funds or documented institutional irregularity. </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--grafite)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg> Actions incompatible with the values of Instituto Brasil Te Ama</li></ul></article></div></div></section>\r\n\r\n<!-- MOOD BAND --><section class=\"section section--white\"><div class=\"container\"><div class=\"mood-band fade-up\"><div class=\"image-slot\" data-slot-id=\"ongs-mood\" data-shape=\"rect\" data-fit=\"cover\" style=\"width:100%;height:auto;aspect-ratio:21/7;;position:relative;overflow:hidden;background:rgba(0,0,0,.04)\"> <span class=\"image-slot__ph\">Image of the environment — hope, hands, community, nature</span></div><div class=\"mood-band__overlay\"><div class=\"mood-band__text\"> <span class=\"eyebrow\">The network</span><p class=\"mood-band__quote\"> A long-term partnership — with clear criteria.</p></div></div></div></div></section>\r\n\r\n<!-- FRENTES TAGS --><section class=\"section section--alt\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Fronts</span><h2 class=\"section-title\"> With what causes<br> The Institute is working.</h2><hr class=\"divider divider--center\"><p class=\"section-sub\" style=\"margin-top: 18px;\"> Instituto Brasil Te Ama operates in 8 active humanitarian areas. NGOs working in any of these areas can apply for registration. </p></div><div style=\"display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; max-width: 880px; margin: 0 auto;\" class=\"fade-up\"> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">Health,</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">Education,</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">Citizenship</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">, Sports</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">, Social Assistance,</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">Social Reintegration,</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">Women&#39;s Rights</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">, People Experiencing Homelessness,</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">Support for the Elderly,</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">International Cooperation</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">, Environment</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">, Women&#39;s Empowerment</span></div></div></section>\r\n\r\n<!-- O QUE A ONG ASSUME --><section class=\"section section--white\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Commitments</span><h2 class=\"section-title\"> What does the NGO assume?<br> when you register. </h2><hr class=\"divider divider--center\"></div><div class=\"grid\" style=\"grid-template-columns: repeat(2, 1fr); gap: 20px; max-width: 920px; margin: 0 auto;\"><article class=\"card fade-up delay-1\"><div class=\"card__body\" style=\"padding: 28px;\"><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 19px; line-height: 1.3; margin-bottom: 10px;\"> Periodic accountability</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> The NGO commits to providing information on how the funds received are being used — in the format and frequency defined in the partnership agreement. </p></div></article><article class=\"card fade-up delay-2\"><div class=\"card__body\" style=\"padding: 28px;\"><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 19px; line-height: 1.3; margin-bottom: 10px;\"> Responsible communication</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> The name and brand of Instituto Brasil Te Ama can only be associated with the NGO&#39;s work with prior authorization and under the terms defined by the Institute. </p></div></article><article class=\"card fade-up delay-3\"><div class=\"card__body\" style=\"padding: 28px;\"><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 19px; line-height: 1.3; margin-bottom: 10px;\"> Compatible public conduct</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> The NGO maintains public conduct aligned with the network&#39;s values — respect, transparency, and the dignity of the people served in all its communications. </p></div></article><article class=\"card fade-up delay-4\"><div class=\"card__body\" style=\"padding: 28px;\"><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 19px; line-height: 1.3; margin-bottom: 10px;\"> Autonomy preserved</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> The Institute does not interfere in the management or internal decisions of the NGO. The partnership is limited to the agreed support and monitoring of resources.</p></div></article></div></div></section>\r\n\r\n<!-- FAQ --><section class=\"section section--alt\" id=\"faq\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Frequently Asked Questions</span><h2 class=\"section-title\"> FAQ — NGOs </h2><hr class=\"divider divider--center\"></div><div class=\"faq-list fade-up\"><details class=\"faq-item\"><summary> Does registration guarantee that my NGO will receive support?</summary><div class=\"faq-item__body\"> No. The registration form initiates an institutional evaluation. Only after analysis, approval, and signing of the partnership agreement does the NGO formally become part of the network and can receive funding.</div></details><details class=\"faq-item\"><summary> What kind of support does the Institute offer?</summary><div class=\"faq-item__body\"> Support can be financial, in the form of supplies, or of another nature — depending on the needs of the NGO and the availability of program resources in each cycle.</div></details><details class=\"faq-item\"><summary> Does the Institute interfere in the management of my NGO?</summary><div class=\"faq-item__body\"> No. The partnership is limited to the agreed-upon support and monitoring of the application of resources. The Institute preserves the autonomy and leadership of each partner NGO.</div></details><details class=\"faq-item\"><summary> Does my NGO need CEBAS certification to register?</summary><div class=\"faq-item__body\"> It is not mandatory. The Institute evaluates the documentation and actual performance of the NGO — CEBAS and other certifications are considered in the prioritization, but are not absolute prerequisites.</div></details><details class=\"faq-item\"><summary> Can I use the Institute&#39;s name in my communications after registering?</summary><div class=\"faq-item__body\"> No. The use of the Institute&#39;s name, brand, and any element depends on prior authorization and is regulated by the partnership agreement. Registration does not authorize any public use.</div></details><details class=\"faq-item\"><summary> How long does it take to receive a response after registering?</summary><div class=\"faq-item__body\"> The Institute will respond within 15 business days of receiving the registration. NGOs that advance in the initial evaluation will be invited for a more in-depth discussion.</div></details><details class=\"faq-item\"><summary> How is follow-up done after approval?</summary><div class=\"faq-item__body\"> Monitoring is defined in the partnership agreement — specifying frequency, accountability format, and communication channel between the Institute and the NGO. The Institute does not interfere in the operation, but monitors the application of resources.</div></details></div></div></section>\r\n\r\n<!-- FORMULÁRIO --><section class=\"section section--white\" id=\"formulario\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Register</span><h2 class=\"section-title\"> Register your NGO —<br> The process starts here.</h2><hr class=\"divider divider--center\"><p class=\"section-sub\" style=\"margin-top: 18px;\"> Please fill in the information below. Registration does not guarantee immediate support — it is the beginning of an institutional evaluation. Our team will get back to you within 15 business days. </p></div><div class=\"form-card fade-up\" style=\"max-width: 880px; margin: 0 auto;\"><form><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\">Name of the NGO</label><input class=\"form-control\" type=\"text\" required></div><div class=\"form-field\"> <label class=\"form-label\">CNPJ</label> <input class=\"form-control\" type=\"text\" placeholder=\"00.000.000/0000-00\" required></div></div><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\">Main area of expertise</label><select class=\"form-control\" required><option value=Selecione> Select</option><option value=\"Saúde\"> Health</option><option value=\"Educação\"> Education</option><option value=Cidadania> Citizenship</option><option value=\"Direitos humanos\"> Human rights</option><option value=\"Empoderamento feminino\"> Women&#39;s empowerment</option><option value=\"Pessoas em situação de rua\"> Homeless people</option><option value=\"Terceira idade\"> Senior citizens</option><option value=Esporte> Sport</option><option value=\"Meio ambiente\"> Environment</option><option value=Outra> Other</option></select></div><div class=\"form-field\"> <label class=\"form-label\">State and city of operation</label> <input class=\"form-control\" type=\"text\" placeholder=\"Ex.: Brasília — DF\" required></div></div><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\">Year of foundation</label> <input class=\"form-control\" type=\"number\" min=\"1900\" max=\"2026\" required></div><div class=\"form-field\"> <label class=\"form-label\">Beneficiaries/month (estimate)</label> <input class=\"form-control\" type=\"text\" required></div></div><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\">Name of legal guardian</label><input class=\"form-control\" type=\"text\" required></div><div class=\"form-field\"> <label class=\"form-label\">Position</label> <input class=\"form-control\" type=\"text\" required></div></div><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\">Institutional email</label><input class=\"form-control\" type=\"email\" required></div><div class=\"form-field\"> <label class=\"form-label\">Phone / WhatsApp</label><input class=\"form-control\" type=\"tel\" required></div></div><div class=\"form-field\"> <label class=\"form-label\">Website or social network (if any)</label><input class=\"form-control\" type=\"url\"></div><div class=\"form-field\"> <label class=\"form-label\">Type of support of interest</label><select class=\"form-control\" required><option value=Selecione> Select</option><option value=Financeiro> Financial</option><option value=Suprimentos> Supplies</option><option value=Ambos> Both</option><option value=\"A definir\"> To be defined</option></select></div><div class=\"form-field\"> <label class=\"form-label\">Job description</label> <textarea class=\"form-control\" placeholder=\"Descreva brevemente o que a ONG faz, quem atende e como opera\" required></textarea></div> <label class=\"form-checkbox\"><input type=\"checkbox\" required><span>I have read and agree to the public selection criteria. I authorize Instituto Brasil Te Ama to contact me for registration analysis.</span></label> <button type=\"submit\" class=\"btn btn--primary btn--lg\" style=\"margin-top: 8px;\">Submit registration →</button><p style=\"font-size: 12px; color: var(--text-gray); margin-top: 16px; line-height: 1.6;\"> Submitting this form does not guarantee immediate approval or support. The Institute will evaluate the application based on public eligibility criteria and will respond within 15 business days.</p></form></div></div></section>" },
  es: { title: "Para ONG — Instituto Brasil Te Ama", description: "Tu ONG puede recibir apoyo de la red Brasil Te Ama. Las organizaciones que trabajan en áreas de vulnerabilidad social pueden registrarse, con criterios claros, rendición de cuentas y respeto a la autonomía.", html: "<section class=\"subhero\"><div class=\"container\"><div class=\"subhero__inner fade-up\"><span class=\"eyebrow eyebrow--bordo\">Para las ONG institucionales</span><h1 class=\"subhero__title\"> Tu ONG puede ir más allá.<br> con una red que <em>ya está en funcionamiento.</em></h1><p class=\"subhero__sub\"> Instituto Brasil Te Ama conecta a organizaciones humanitarias verificadas con una red de apoyo estructurada, que cuenta con credenciales de la Soberana Orden de los Caballeros de Malta OSJ, empresas asociadas y transparencia en cada paso.</p><div style=\"margin-top: 28px; display: flex; gap: 14px; flex-wrap: wrap;\"> <a href=\"#formulario\" class=\"btn btn--primary\">Registrar mi ONG →</a> <a href=\"#criterios\" class=\"btn btn--secondary\">Entender los criterios ↓</a></div></div></div></section>\r\n\r\n<!-- O QUE OFERECEMOS --><section class=\"section section--white\"><div class=\"container\"><div class=\"section-header fade-up\"> <span class=\"eyebrow\">Lo que ofrecemos</span><h2 class=\"section-title\"> Lo que ofrece el Instituto<br> para las ONG.</h2><hr class=\"divider\"><p class=\"section-sub\" style=\"margin-top: 18px;\"> No se trata de una donación puntual. No se trata de dar visibilidad a la campaña. Se trata de una colaboración a largo plazo, con criterios claros, un proceso transparente y un compromiso mutuo. </p></div><div class=\"grid\" style=\"grid-template-columns: repeat(3, 1fr); gap: 20px;\"><article class=\"card fade-up delay-1\"><div class=\"card__body\" style=\"padding: 28px;\"><div style=\"width:42px; height:42px; border-radius: 10px; background: var(--blush); display: inline-flex; align-items: center; justify-content: center; color: var(--bordo); margin-bottom: 14px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 18px; line-height: 1.3; margin-bottom: 10px;\"> Apoyo financiero o estructural</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> Los recursos generados por el programa Selo Brasil Te Ama se destinan a ONG registradas, en forma de ayuda financiera o suministros. </p></div></article><article class=\"card fade-up delay-2\"><div class=\"card__body\" style=\"padding: 28px;\"><div style=\"width:42px; height:42px; border-radius: 10px; background: var(--blush); display: inline-flex; align-items: center; justify-content: center; color: var(--bordo); margin-bottom: 14px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 18px; line-height: 1.3; margin-bottom: 10px;\"> Visibilidad institucional</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> Las ONG apoyadas son mencionadas en las comunicaciones públicas del Instituto —en el sitio web, los informes y los materiales promocionales— con discreción y respeto. </p></div></article><article class=\"card fade-up delay-3\"><div class=\"card__body\" style=\"padding: 28px;\"><div style=\"width:42px; height:42px; border-radius: 10px; background: var(--blush); display: inline-flex; align-items: center; justify-content: center; color: var(--bordo); margin-bottom: 14px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 18px; line-height: 1.3; margin-bottom: 10px;\"> respaldo de la asociación</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> La asociación con Instituto Brasil Te Ama y la Soberana Orden de los Caballeros de Malta OSJ confiere mayor credibilidad ante donantes, socios y organismos públicos. </p></div></article><article class=\"card fade-up delay-4\"><div class=\"card__body\" style=\"padding: 28px;\"><div style=\"width:42px; height:42px; border-radius: 10px; background: var(--blush); display: inline-flex; align-items: center; justify-content: center; color: var(--bordo); margin-bottom: 14px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 18px; line-height: 1.3; margin-bottom: 10px;\"> Apoyo estructurado y continuo</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> No se trata de una acción aislada. Es un flujo constante de apoyo generado por las empresas asociadas al Instituto. </p></div></article><article class=\"card fade-up delay-1\"><div class=\"card__body\" style=\"padding: 28px;\"><div style=\"width:42px; height:42px; border-radius: 10px; background: var(--blush); display: inline-flex; align-items: center; justify-content: center; color: var(--bordo); margin-bottom: 14px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 18px; line-height: 1.3; margin-bottom: 10px;\"> Transparencia en cada paso.</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> El Instituto documenta el destino de cada subvención. Su organización sabe qué recibe, cuándo proviene y de dónde proviene. </p></div></article><article class=\"card fade-up delay-2\"><div class=\"card__body\" style=\"padding: 28px;\"><div style=\"width:42px; height:42px; border-radius: 10px; background: var(--blush); display: inline-flex; align-items: center; justify-content: center; color: var(--bordo); margin-bottom: 14px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 18px; line-height: 1.3; margin-bottom: 10px;\"> Autonomía preservada</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> La colaboración se limita al apoyo acordado. El Instituto no interfiere en la gestión ni en las decisiones internas de la ONG.</p></div></article></div></div></section>\r\n\r\n<!-- COMO FUNCIONA O PROCESSO --><section class=\"section section--alt\" id=\"processo\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Cómo funciona</span><h2 class=\"section-title\"> ¿Cómo funciona el proceso?<br> selección de ONG. </h2><hr class=\"divider divider--center\"></div><div class=\"steps\"><article class=\"step fade-up delay-1\"><div class=\"step__num\"> 01</div><h3 class=\"step__title\"> Registro</h3><p class=\"step__desc\"> Su ONG completa el formulario con los datos institucionales, el área de actividad y una descripción de su trabajo. No se requiere documentación en esta etapa.</p></article><article class=\"step fade-up delay-2\"><div class=\"step__num\"> 02</div><h3 class=\"step__title\"> Análisis institucional</h3><p class=\"step__desc\"> El Instituto evalúa la inscripción según criterios públicos. El análisis lo realiza el equipo interno en un plazo de 15 días hábiles.</p></article><article class=\"step fade-up delay-3\"><div class=\"step__num\"> 03</div><h3 class=\"step__title\"> Alineación</h3><p class=\"step__desc\"> Reunión para definir términos, áreas de enfoque y expectativas. Las ONG no aprobadas reciben retroalimentación y orientación cuando es posible.</p></article><article class=\"step fade-up delay-4\"><div class=\"step__num\"> 04</div><h3 class=\"step__title\"> Asociación activa</h3><p class=\"step__desc\"> La ONG pasará a formar parte de la red y recibirá apoyo estructurado, con un acuerdo de colaboración firmado y un seguimiento periódico.</p></article></div></div></section>\r\n\r\n<!-- CRITÉRIOS --><section class=\"section section--white\" id=\"criterios\"><div class=\"container\"><div class=\"section-header fade-up\"> <span class=\"eyebrow\">Elegibilidad</span><h2 class=\"section-title\"> ¿Cuáles son los criterios?<br> selección.</h2><hr class=\"divider\"><p class=\"section-sub\" style=\"margin-top: 18px;\"> Unos criterios claros protegen la integridad de la red, tanto para las empresas asociadas como para el público y las organizaciones que la integran. </p></div><div class=\"grid\" style=\"grid-template-columns: 1fr 1fr 1fr; gap: 16px;\"><article class=\"card fade-up delay-1\" style=\"padding: 0;\"><div style=\"padding: 18px 24px; background: var(--blush); border-bottom: 1px solid var(--border);\"><p style=\"font-size: 11px; font-weight: 700; letter-spacing: 2.5px; color: var(--bordo); text-transform: uppercase;\"> Criterios obligatorios </p></div><ul style=\"list-style: none; padding: 22px 24px; display: flex; flex-direction: column; gap: 12px;\"><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polyline points=\"20 6 9 17 4 12\"/></svg> CNPJ (número de identificación fiscal de la empresa brasileña) activo y en regla, sin restricciones de registro importantes. </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polyline points=\"20 6 9 17 4 12\"/></svg> Experiencia demostrable en un área compatible con los valores del Instituto. </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polyline points=\"20 6 9 17 4 12\"/></svg> Ausencia de antecedentes públicos de irregularidades graves o malversación de fondos. </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polyline points=\"20 6 9 17 4 12\"/></svg> Apertura para rendir cuentas al Instituto </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polyline points=\"20 6 9 17 4 12\"/></svg> Capacidad para recibir apoyo y aplicarlo de forma verificable. </li></ul></article><article class=\"card fade-up delay-2\" style=\"padding: 0;\"><div style=\"padding: 18px 24px; background: rgba(183,154,99,.12); border-bottom: 1px solid var(--border);\"><p style=\"font-size: 11px; font-weight: 700; letter-spacing: 2.5px; color: var(--dourado); text-transform: uppercase;\"> Aumentan la prioridad. </p></div><ul style=\"list-style: none; padding: 22px 24px; display: flex; flex-direction: column; gap: 12px;\"><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--dourado)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polygon points=\"12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2\"/></svg> Trayectoria consistente y larga trayectoria. </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--dourado)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polygon points=\"12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2\"/></svg> Presencia pública verificable: sitio web, redes sociales o informes. </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--dourado)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polygon points=\"12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2\"/></svg> Cobertura geográfica estratégica o cobertura complementaria a las ONG que ya reciben apoyo. </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--dourado)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polygon points=\"12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2\"/></svg> Alineación temática con las áreas prioritarias del Instituto. </li></ul></article><article class=\"card fade-up delay-3\" style=\"padding: 0;\"><div style=\"padding: 18px 24px; background: rgba(0,0,0,.04); border-bottom: 1px solid var(--border);\"><p style=\"font-size: 11px; font-weight: 700; letter-spacing: 2.5px; color: var(--grafite); text-transform: uppercase;\"> Impiden la aprobación. </p></div><ul style=\"list-style: none; padding: 22px 24px; display: flex; flex-direction: column; gap: 12px;\"><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--grafite)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg> CNPJ inactivo o CNPJ con irregularidad grave sin resolver. </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--grafite)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg> Antecedentes de malversación de fondos o irregularidades institucionales documentadas. </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--grafite)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg> Acciones incompatibles con los valores de Instituto Brasil Te Ama</li></ul></article></div></div></section>\r\n\r\n<!-- MOOD BAND --><section class=\"section section--white\"><div class=\"container\"><div class=\"mood-band fade-up\"><div class=\"image-slot\" data-slot-id=\"ongs-mood\" data-shape=\"rect\" data-fit=\"cover\" style=\"width:100%;height:auto;aspect-ratio:21/7;;position:relative;overflow:hidden;background:rgba(0,0,0,.04)\"> <span class=\"image-slot__ph\">Imagen del entorno: esperanza, manos, comunidad, naturaleza</span></div><div class=\"mood-band__overlay\"><div class=\"mood-band__text\"> <span class=\"eyebrow\">La red</span><p class=\"mood-band__quote\"> Una colaboración a largo plazo, con criterios claros.</p></div></div></div></div></section>\r\n\r\n<!-- FRENTES TAGS --><section class=\"section section--alt\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Frentes</span><h2 class=\"section-title\"> Con qué causa<br> El Instituto está trabajando.</h2><hr class=\"divider divider--center\"><p class=\"section-sub\" style=\"margin-top: 18px;\"> Instituto Brasil Te Ama opera en 8 áreas humanitarias activas. Las ONG que trabajan en cualquiera de estas áreas pueden solicitar su registro. </p></div><div style=\"display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; max-width: 880px; margin: 0 auto;\" class=\"fade-up\"> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">Salud,</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">Educación,</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">Ciudadanía</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">, Deportes</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">, Asistencia Social,</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">Reintegración Social,</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">Derechos de la Mujer</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">, Personas sin Hogar,</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">Apoyo a las Personas Mayores,</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">Cooperación Internacional</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">, Medio Ambiente</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">, Empoderamiento de la Mujer</span></div></div></section>\r\n\r\n<!-- O QUE A ONG ASSUME --><section class=\"section section--white\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Compromisos</span><h2 class=\"section-title\"> ¿Qué supone la ONG?<br> cuando te registres. </h2><hr class=\"divider divider--center\"></div><div class=\"grid\" style=\"grid-template-columns: repeat(2, 1fr); gap: 20px; max-width: 920px; margin: 0 auto;\"><article class=\"card fade-up delay-1\"><div class=\"card__body\" style=\"padding: 28px;\"><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 19px; line-height: 1.3; margin-bottom: 10px;\"> Rendición de cuentas periódica</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> La ONG se compromete a proporcionar información sobre cómo se están utilizando los fondos recibidos, en el formato y con la frecuencia definidos en el acuerdo de colaboración. </p></div></article><article class=\"card fade-up delay-2\"><div class=\"card__body\" style=\"padding: 28px;\"><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 19px; line-height: 1.3; margin-bottom: 10px;\"> Comunicación responsable</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> El nombre y la marca Instituto Brasil Te Ama solo podrán asociarse al trabajo de la ONG con autorización previa y bajo los términos definidos por el Instituto. </p></div></article><article class=\"card fade-up delay-3\"><div class=\"card__body\" style=\"padding: 28px;\"><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 19px; line-height: 1.3; margin-bottom: 10px;\"> Conducta pública compatible</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> La ONG mantiene una conducta pública acorde con los valores de la red: respeto, transparencia y dignidad de las personas a las que sirve en todas sus comunicaciones. </p></div></article><article class=\"card fade-up delay-4\"><div class=\"card__body\" style=\"padding: 28px;\"><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 19px; line-height: 1.3; margin-bottom: 10px;\"> Autonomía preservada</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> El Instituto no interfiere en la gestión ni en las decisiones internas de la ONG. La colaboración se limita al apoyo y seguimiento de los recursos acordados.</p></div></article></div></div></section>\r\n\r\n<!-- FAQ --><section class=\"section section--alt\" id=\"faq\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Preguntas frecuentes</span><h2 class=\"section-title\"> Preguntas frecuentes — ONG </h2><hr class=\"divider divider--center\"></div><div class=\"faq-list fade-up\"><details class=\"faq-item\"><summary> ¿El registro garantiza que mi ONG recibirá apoyo?</summary><div class=\"faq-item__body\"> No. El formulario de inscripción inicia una evaluación institucional. Solo después del análisis, la aprobación y la firma del acuerdo de colaboración, la ONG pasa a formar parte formalmente de la red y puede recibir financiación.</div></details><details class=\"faq-item\"><summary> ¿Qué tipo de apoyo ofrece el Instituto?</summary><div class=\"faq-item__body\"> El apoyo puede ser financiero, en forma de suministros o de otra índole, dependiendo de las necesidades de la ONG y de la disponibilidad de recursos del programa en cada ciclo.</div></details><details class=\"faq-item\"><summary> ¿Interfiere el Instituto en la gestión de mi ONG?</summary><div class=\"faq-item__body\"> No. La colaboración se limita al apoyo y seguimiento acordados para la aplicación de los recursos. El Instituto preserva la autonomía y el liderazgo de cada ONG asociada.</div></details><details class=\"faq-item\"><summary> ¿Mi ONG necesita la certificación CEBAS para registrarse?</summary><div class=\"faq-item__body\"> No es obligatorio. El Instituto evalúa la documentación y el desempeño real de la ONG; las certificaciones CEBAS y otras se tienen en cuenta en la priorización, pero no son requisitos indispensables.</div></details><details class=\"faq-item\"><summary> ¿Puedo usar el nombre del Instituto en mis comunicaciones después de registrarme?</summary><div class=\"faq-item__body\"> No. El uso del nombre, la marca y cualquier otro elemento del Instituto requiere autorización previa y está regulado por el acuerdo de colaboración. El registro no autoriza su uso público.</div></details><details class=\"faq-item\"><summary> ¿Cuánto tiempo se tarda en recibir una respuesta después de registrarse?</summary><div class=\"faq-item__body\"> El Instituto responderá en un plazo de 15 días hábiles a partir de la recepción de la inscripción. Las ONG que superen la evaluación inicial serán invitadas a una reunión más exhaustiva.</div></details><details class=\"faq-item\"><summary> ¿Cómo se realiza el seguimiento después de la aprobación?</summary><div class=\"faq-item__body\"> El seguimiento se define en el acuerdo de colaboración, especificando la frecuencia, el formato de rendición de cuentas y el canal de comunicación entre el Instituto y la ONG. El Instituto no interviene en la operación, sino que supervisa la aplicación de los recursos.</div></details></div></div></section>\r\n\r\n<!-- FORMULÁRIO --><section class=\"section section--white\" id=\"formulario\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Registro</span><h2 class=\"section-title\"> Registra tu ONG —<br> El proceso comienza aquí.</h2><hr class=\"divider divider--center\"><p class=\"section-sub\" style=\"margin-top: 18px;\"> Por favor, complete la información a continuación. El registro no garantiza asistencia inmediata; es el inicio de una evaluación institucional. Nuestro equipo se pondrá en contacto con usted en un plazo de 15 días hábiles. </p></div><div class=\"form-card fade-up\" style=\"max-width: 880px; margin: 0 auto;\"><form><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\">Nombre de la ONG</label><input class=\"form-control\" type=\"text\" required></div><div class=\"form-field\"> <label class=\"form-label\">CNPJ</label> <input class=\"form-control\" type=\"text\" placeholder=\"00.000.000/0000-00\" required></div></div><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\">Área principal de especialización</label><select class=\"form-control\" required><option value=Selecione> Seleccionar</option><option value=\"Saúde\"> Salud</option><option value=\"Educação\"> Educación</option><option value=Cidadania> Ciudadanía</option><option value=\"Direitos humanos\"> Derechos humanos</option><option value=\"Empoderamento feminino\"> Empoderamiento de la mujer</option><option value=\"Pessoas em situação de rua\"> personas sin hogar</option><option value=\"Terceira idade\"> Personas mayores</option><option value=Esporte> Deporte</option><option value=\"Meio ambiente\"> Ambiente</option><option value=Outra> Otro</option></select></div><div class=\"form-field\"> <label class=\"form-label\">Estado y ciudad de operación</label> <input class=\"form-control\" type=\"text\" placeholder=\"Ex.: Brasília — DF\" required></div></div><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\">Año de fundación</label> <input class=\"form-control\" type=\"number\" min=\"1900\" max=\"2026\" required></div><div class=\"form-field\"> <label class=\"form-label\">Beneficiarios/mes (estimado)</label> <input class=\"form-control\" type=\"text\" required></div></div><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\">Nombre del tutor legal</label><input class=\"form-control\" type=\"text\" required></div><div class=\"form-field\"> <label class=\"form-label\">Posición</label> <input class=\"form-control\" type=\"text\" required></div></div><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\">Correo electrónico institucional</label><input class=\"form-control\" type=\"email\" required></div><div class=\"form-field\"> <label class=\"form-label\">Teléfono / WhatsApp</label><input class=\"form-control\" type=\"tel\" required></div></div><div class=\"form-field\"> <label class=\"form-label\">Sitio web o red social (si corresponde)</label><input class=\"form-control\" type=\"url\"></div><div class=\"form-field\"> <label class=\"form-label\">Tipo de apoyo de interés</label><select class=\"form-control\" required><option value=Selecione> Seleccionar</option><option value=Financeiro> Financiero</option><option value=Suprimentos> Suministros</option><option value=Ambos> Ambos</option><option value=\"A definir\"> Por definir</option></select></div><div class=\"form-field\"> <label class=\"form-label\">Descripción del trabajo</label> <textarea class=\"form-control\" placeholder=\"Descreva brevemente o que a ONG faz, quem atende e como opera\" required></textarea></div> <label class=\"form-checkbox\"><input type=\"checkbox\" required><span>He leído y acepto los criterios de selección pública. Autorizo a Instituto Brasil Te Ama a contactarme para el análisis de mi registro.</span></label> <button type=\"submit\" class=\"btn btn--primary btn--lg\" style=\"margin-top: 8px;\">Enviar registro →</button><p style=\"font-size: 12px; color: var(--text-gray); margin-top: 16px; line-height: 1.6;\"> El envío de este formulario no garantiza la aprobación ni el apoyo inmediatos. El Instituto evaluará la solicitud según los criterios de elegibilidad establecidos y responderá en un plazo de 15 días hábiles.</p></form></div></div></section>" },
  it: { title: "Per le ONG — Instituto Brasil Te Ama", description: "La vostra ONG può ricevere supporto dalla rete Brasil Te Ama. Le organizzazioni che operano in aree di vulnerabilità sociale possono registrarsi, nel rispetto di criteri chiari, responsabilità e autonomia.", html: "<section class=\"subhero\"><div class=\"container\"><div class=\"subhero__inner fade-up\"><span class=\"eyebrow eyebrow--bordo\">Per le ONG istituzionali</span><h1 class=\"subhero__title\"> La vostra ONG può fare di più —<br> con una rete <em>già in movimento.</em></h1><p class=\"subhero__sub\"> Instituto Brasil Te Ama collega organizzazioni umanitarie verificate a una rete di supporto strutturata, con credenziali del Sovrano Ordine dei Cavalieri di Malta OSJ, aziende partner e trasparenza in ogni fase.</p><div style=\"margin-top: 28px; display: flex; gap: 14px; flex-wrap: wrap;\"> <a href=\"#formulario\" class=\"btn btn--primary\">Registra la mia ONG →</a> <a href=\"#criterios\" class=\"btn btn--secondary\">Scopri i criteri ↓</a></div></div></div></section>\r\n\r\n<!-- O QUE OFERECEMOS --><section class=\"section section--white\"><div class=\"container\"><div class=\"section-header fade-up\"> <span class=\"eyebrow\">Cosa offriamo</span><h2 class=\"section-title\"> Cosa offre l&#39;Istituto<br> per le ONG.</h2><hr class=\"divider\"><p class=\"section-sub\" style=\"margin-top: 18px;\"> Non si tratta di una donazione una tantum. Non è una questione di visibilità per la campagna elettorale. È una partnership a lungo termine, con criteri chiari, un processo trasparente e un impegno reciproco. </p></div><div class=\"grid\" style=\"grid-template-columns: repeat(3, 1fr); gap: 20px;\"><article class=\"card fade-up delay-1\"><div class=\"card__body\" style=\"padding: 28px;\"><div style=\"width:42px; height:42px; border-radius: 10px; background: var(--blush); display: inline-flex; align-items: center; justify-content: center; color: var(--bordo); margin-bottom: 14px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 18px; line-height: 1.3; margin-bottom: 10px;\"> Sostegno finanziario o strutturale</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> Le risorse generate dal programma Selo Brasil Te Ama vengono destinate alle ONG registrate, sotto forma di aiuti finanziari o forniture. </p></div></article><article class=\"card fade-up delay-2\"><div class=\"card__body\" style=\"padding: 28px;\"><div style=\"width:42px; height:42px; border-radius: 10px; background: var(--blush); display: inline-flex; align-items: center; justify-content: center; color: var(--bordo); margin-bottom: 14px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 18px; line-height: 1.3; margin-bottom: 10px;\"> visibilità istituzionale</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> Le ONG sostenute dall&#39;Istituto vengono menzionate nelle sue comunicazioni pubbliche – sul sito web, nei rapporti e nel materiale promozionale – con discrezione e rispetto. </p></div></article><article class=\"card fade-up delay-3\"><div class=\"card__body\" style=\"padding: 28px;\"><div style=\"width:42px; height:42px; border-radius: 10px; background: var(--blush); display: inline-flex; align-items: center; justify-content: center; color: var(--bordo); margin-bottom: 14px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 18px; line-height: 1.3; margin-bottom: 10px;\"> Approvazione della partnership</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> L&#39;associazione con Instituto Brasil Te Ama e il Sovrano Ordine dei Cavalieri di Malta OSJ conferisce ulteriore credibilità agli occhi di donatori, partner ed enti pubblici. </p></div></article><article class=\"card fade-up delay-4\"><div class=\"card__body\" style=\"padding: 28px;\"><div style=\"width:42px; height:42px; border-radius: 10px; background: var(--blush); display: inline-flex; align-items: center; justify-content: center; color: var(--bordo); margin-bottom: 14px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 18px; line-height: 1.3; margin-bottom: 10px;\"> Supporto strutturato e continuativo</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> Non si tratta di un&#39;azione isolata. È un flusso di supporto generato dalle aziende partner dell&#39;Istituto. </p></div></article><article class=\"card fade-up delay-1\"><div class=\"card__body\" style=\"padding: 28px;\"><div style=\"width:42px; height:42px; border-radius: 10px; background: var(--blush); display: inline-flex; align-items: center; justify-content: center; color: var(--bordo); margin-bottom: 14px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 18px; line-height: 1.3; margin-bottom: 10px;\"> Trasparenza in ogni fase.</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> L&#39;Istituto documenta la destinazione di ogni sovvenzione. La vostra organizzazione sa cosa riceve, quando proviene e da dove proviene. </p></div></article><article class=\"card fade-up delay-2\"><div class=\"card__body\" style=\"padding: 28px;\"><div style=\"width:42px; height:42px; border-radius: 10px; background: var(--blush); display: inline-flex; align-items: center; justify-content: center; color: var(--bordo); margin-bottom: 14px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 18px; line-height: 1.3; margin-bottom: 10px;\"> Autonomia garantita</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> La collaborazione si limita al supporto concordato. L&#39;Istituto non interferisce nella gestione o nelle decisioni interne dell&#39;ONG.</p></div></article></div></div></section>\r\n\r\n<!-- COMO FUNCIONA O PROCESSO --><section class=\"section section--alt\" id=\"processo\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Come funziona</span><h2 class=\"section-title\"> Come funziona il processo?<br> selezione delle ONG. </h2><hr class=\"divider divider--center\"></div><div class=\"steps\"><article class=\"step fade-up delay-1\"><div class=\"step__num\"> 01</div><h3 class=\"step__title\"> Registro</h3><p class=\"step__desc\"> La vostra ONG compila il modulo con i dati istituzionali, l&#39;area di attività e una descrizione del proprio lavoro. In questa fase non è richiesto alcun documento.</p></article><article class=\"step fade-up delay-2\"><div class=\"step__num\"> 02</div><h3 class=\"step__title\"> Analisi istituzionale</h3><p class=\"step__desc\"> L&#39;Istituto valuta la registrazione sulla base di criteri pubblici. L&#39;analisi viene condotta dal team interno entro 15 giorni lavorativi.</p></article><article class=\"step fade-up delay-3\"><div class=\"step__num\"> 03</div><h3 class=\"step__title\"> Allineamento</h3><p class=\"step__desc\"> Riunione per definire termini, aree di intervento e aspettative. Le ONG non ancora accreditate ricevono un feedback e, ove possibile, indicazioni.</p></article><article class=\"step fade-up delay-4\"><div class=\"step__num\"> 04</div><h3 class=\"step__title\"> Partnership attiva</h3><p class=\"step__desc\"> L&#39;ONG entrerà a far parte della rete e riceverà un supporto strutturato, con un accordo di partenariato firmato e un monitoraggio periodico.</p></article></div></div></section>\r\n\r\n<!-- CRITÉRIOS --><section class=\"section section--white\" id=\"criterios\"><div class=\"container\"><div class=\"section-header fade-up\"> <span class=\"eyebrow\">Requisiti di ammissibilità</span><h2 class=\"section-title\"> Quali sono i criteri?<br> selezione.</h2><hr class=\"divider\"><p class=\"section-sub\" style=\"margin-top: 18px;\"> Criteri chiari tutelano l&#39;integrità della rete, a vantaggio delle aziende partner, del pubblico e delle organizzazioni che la compongono. </p></div><div class=\"grid\" style=\"grid-template-columns: 1fr 1fr 1fr; gap: 16px;\"><article class=\"card fade-up delay-1\" style=\"padding: 0;\"><div style=\"padding: 18px 24px; background: var(--blush); border-bottom: 1px solid var(--border);\"><p style=\"font-size: 11px; font-weight: 700; letter-spacing: 2.5px; color: var(--bordo); text-transform: uppercase;\"> Criteri obbligatori </p></div><ul style=\"list-style: none; padding: 22px 24px; display: flex; flex-direction: column; gap: 12px;\"><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polyline points=\"20 6 9 17 4 12\"/></svg> Codice fiscale (CNPJ) aziendale brasiliano attivo e in regola, senza gravi restrizioni di registrazione. </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polyline points=\"20 6 9 17 4 12\"/></svg> Comprovata esperienza in un settore compatibile con i valori dell&#39;Istituto. </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polyline points=\"20 6 9 17 4 12\"/></svg> Assenza di precedenti pubblici di gravi irregolarità o appropriazione indebita di fondi. </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polyline points=\"20 6 9 17 4 12\"/></svg> Apertura alla rendicontazione all&#39;Istituto </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polyline points=\"20 6 9 17 4 12\"/></svg> Capacità di ricevere supporto e di utilizzarlo in modo verificabile. </li></ul></article><article class=\"card fade-up delay-2\" style=\"padding: 0;\"><div style=\"padding: 18px 24px; background: rgba(183,154,99,.12); border-bottom: 1px solid var(--border);\"><p style=\"font-size: 11px; font-weight: 700; letter-spacing: 2.5px; color: var(--dourado); text-transform: uppercase;\"> Aumentano la priorità. </p></div><ul style=\"list-style: none; padding: 22px 24px; display: flex; flex-direction: column; gap: 12px;\"><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--dourado)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polygon points=\"12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2\"/></svg> Comprovata esperienza e lunga attività. </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--dourado)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polygon points=\"12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2\"/></svg> Presenza pubblica verificabile: sito web, social media o report. </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--dourado)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polygon points=\"12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2\"/></svg> Copertura geografica strategica o copertura complementare a quella delle ONG già supportate. </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--dourado)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polygon points=\"12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2\"/></svg> Allineamento tematico con le aree prioritarie dell&#39;Istituto. </li></ul></article><article class=\"card fade-up delay-3\" style=\"padding: 0;\"><div style=\"padding: 18px 24px; background: rgba(0,0,0,.04); border-bottom: 1px solid var(--border);\"><p style=\"font-size: 11px; font-weight: 700; letter-spacing: 2.5px; color: var(--grafite); text-transform: uppercase;\"> Impediscono l&#39;approvazione. </p></div><ul style=\"list-style: none; padding: 22px 24px; display: flex; flex-direction: column; gap: 12px;\"><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--grafite)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg> Anomalia congenita della giunzione neuromuscolare (CNPJ) inattiva o CNPJ con grave irregolarità irrisolta. </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--grafite)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg> Precedenti di appropriazione indebita di fondi o irregolarità istituzionali documentate. </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--grafite)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg> Azioni incompatibili con i valori di Instituto Brasil Te Ama</li></ul></article></div></div></section>\r\n\r\n<!-- MOOD BAND --><section class=\"section section--white\"><div class=\"container\"><div class=\"mood-band fade-up\"><div class=\"image-slot\" data-slot-id=\"ongs-mood\" data-shape=\"rect\" data-fit=\"cover\" style=\"width:100%;height:auto;aspect-ratio:21/7;;position:relative;overflow:hidden;background:rgba(0,0,0,.04)\"> <span class=\"image-slot__ph\">Immagine dell&#39;ambiente: speranza, mani, comunità, natura</span></div><div class=\"mood-band__overlay\"><div class=\"mood-band__text\"> <span class=\"eyebrow\">La rete</span><p class=\"mood-band__quote\"> Una partnership a lungo termine, con criteri chiari.</p></div></div></div></div></section>\r\n\r\n<!-- FRENTES TAGS --><section class=\"section section--alt\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Fronti</span><h2 class=\"section-title\"> Con quali cause<br> L&#39;Istituto è al lavoro.</h2><hr class=\"divider divider--center\"><p class=\"section-sub\" style=\"margin-top: 18px;\"> Instituto Brasil Te Ama opera in 8 aree umanitarie attive. Le ONG che lavorano in una qualsiasi di queste aree possono richiedere la registrazione. </p></div><div style=\"display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; max-width: 880px; margin: 0 auto;\" class=\"fade-up\"> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">Salute,</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">Istruzione,</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">Cittadinanza</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">, Sport</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">, Assistenza sociale,</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">Reinserimento sociale,</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">Diritti delle donne</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">, Persone senza fissa dimora,</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">Sostegno agli anziani,</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">Cooperazione internazionale</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">, Ambiente</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">, Empowerment femminile</span></div></div></section>\r\n\r\n<!-- O QUE A ONG ASSUME --><section class=\"section section--white\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Impegni</span><h2 class=\"section-title\"> Cosa presuppone l&#39;ONG?<br> al momento della registrazione. </h2><hr class=\"divider divider--center\"></div><div class=\"grid\" style=\"grid-template-columns: repeat(2, 1fr); gap: 20px; max-width: 920px; margin: 0 auto;\"><article class=\"card fade-up delay-1\"><div class=\"card__body\" style=\"padding: 28px;\"><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 19px; line-height: 1.3; margin-bottom: 10px;\"> Responsabilità periodica</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> L&#39;ONG si impegna a fornire informazioni sull&#39;utilizzo dei fondi ricevuti, secondo il formato e la frequenza definiti nell&#39;accordo di partenariato. </p></div></article><article class=\"card fade-up delay-2\"><div class=\"card__body\" style=\"padding: 28px;\"><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 19px; line-height: 1.3; margin-bottom: 10px;\"> Comunicazione responsabile</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> Il nome e il marchio Instituto Brasil Te Ama possono essere associati all&#39;attività dell&#39;ONG solo previa autorizzazione e secondo i termini definiti dall&#39;Istituto. </p></div></article><article class=\"card fade-up delay-3\"><div class=\"card__body\" style=\"padding: 28px;\"><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 19px; line-height: 1.3; margin-bottom: 10px;\"> condotta pubblica compatibile</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> L&#39;ONG mantiene una condotta pubblica coerente con i valori della rete: rispetto, trasparenza e dignità delle persone a cui si rivolge, in tutte le sue comunicazioni. </p></div></article><article class=\"card fade-up delay-4\"><div class=\"card__body\" style=\"padding: 28px;\"><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 19px; line-height: 1.3; margin-bottom: 10px;\"> Autonomia garantita</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> L&#39;Istituto non interferisce nella gestione o nelle decisioni interne dell&#39;ONG. La collaborazione si limita al supporto concordato e al monitoraggio delle risorse.</p></div></article></div></div></section>\r\n\r\n<!-- FAQ --><section class=\"section section--alt\" id=\"faq\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Domande frequenti</span><h2 class=\"section-title\"> FAQ — ONG </h2><hr class=\"divider divider--center\"></div><div class=\"faq-list fade-up\"><details class=\"faq-item\"><summary> La registrazione garantisce che la mia ONG riceverà sostegno?</summary><div class=\"faq-item__body\"> No. Il modulo di registrazione avvia una valutazione istituzionale. Solo dopo l&#39;analisi, l&#39;approvazione e la firma dell&#39;accordo di partenariato, l&#39;ONG entra formalmente a far parte della rete e può ricevere finanziamenti.</div></details><details class=\"faq-item\"><summary> Che tipo di supporto offre l&#39;Istituto?</summary><div class=\"faq-item__body\"> Il supporto può essere finanziario, sotto forma di materiali, o di altra natura, a seconda delle esigenze dell&#39;ONG e della disponibilità di risorse per il programma in ogni ciclo.</div></details><details class=\"faq-item\"><summary> L&#39;Istituto interferisce nella gestione della mia ONG?</summary><div class=\"faq-item__body\"> No. La collaborazione si limita al supporto concordato e al monitoraggio dell&#39;impiego delle risorse. L&#39;Istituto preserva l&#39;autonomia e la leadership di ciascuna ONG partner.</div></details><details class=\"faq-item\"><summary> La mia ONG necessita della certificazione CEBAS per registrarsi?</summary><div class=\"faq-item__body\"> Non è obbligatorio. L&#39;Istituto valuta la documentazione e le prestazioni effettive dell&#39;ONG: le certificazioni CEBAS e altre vengono prese in considerazione nella definizione delle priorità, ma non sono prerequisiti assoluti.</div></details><details class=\"faq-item\"><summary> Posso utilizzare il nome dell&#39;Istituto nelle mie comunicazioni dopo essermi registrato?</summary><div class=\"faq-item__body\"> No. L&#39;utilizzo del nome, del marchio e di qualsiasi elemento dell&#39;Istituto è soggetto ad autorizzazione preventiva ed è regolato dall&#39;accordo di partnership. La registrazione non autorizza alcun utilizzo pubblico.</div></details><details class=\"faq-item\"><summary> Quanto tempo ci vuole per ricevere una risposta dopo la registrazione?</summary><div class=\"faq-item__body\"> L&#39;Istituto risponderà entro 15 giorni lavorativi dalla ricezione della registrazione. Le ONG che supereranno la fase di valutazione iniziale saranno invitate a un colloquio più approfondito.</div></details><details class=\"faq-item\"><summary> Come si procede dopo l&#39;approvazione?</summary><div class=\"faq-item__body\"> Il monitoraggio è definito nell&#39;accordo di partenariato, che specifica la frequenza, le modalità di rendicontazione e il canale di comunicazione tra l&#39;Istituto e l&#39;ONG. L&#39;Istituto non interferisce nella gestione operativa, ma monitora l&#39;impiego delle risorse.</div></details></div></div></section>\r\n\r\n<!-- FORMULÁRIO --><section class=\"section section--white\" id=\"formulario\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Registro</span><h2 class=\"section-title\"> Registra la tua ONG —<br> Il processo inizia qui.</h2><hr class=\"divider divider--center\"><p class=\"section-sub\" style=\"margin-top: 18px;\"> Si prega di compilare le informazioni sottostanti. La registrazione non garantisce un supporto immediato, ma rappresenta l&#39;inizio di una valutazione istituzionale. Il nostro team vi ricontatterà entro 15 giorni lavorativi. </p></div><div class=\"form-card fade-up\" style=\"max-width: 880px; margin: 0 auto;\"><form><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\">Nome dell&#39;ONG</label><input class=\"form-control\" type=\"text\" required></div><div class=\"form-field\"> <label class=\"form-label\">CNPJ</label> <input class=\"form-control\" type=\"text\" placeholder=\"00.000.000/0000-00\" required></div></div><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\">Principale area di competenza</label><select class=\"form-control\" required><option value=Selecione> Selezionare</option><option value=\"Saúde\"> Salute</option><option value=\"Educação\"> Preparazione</option><option value=Cidadania> Cittadinanza</option><option value=\"Direitos humanos\"> diritti umani</option><option value=\"Empoderamento feminino\"> emancipazione femminile</option><option value=\"Pessoas em situação de rua\"> Persone senza fissa dimora</option><option value=\"Terceira idade\"> anziani</option><option value=Esporte> Sport</option><option value=\"Meio ambiente\"> Ambiente</option><option value=Outra> Altro</option></select></div><div class=\"form-field\"> <label class=\"form-label\">Stato e città di esercizio</label> <input class=\"form-control\" type=\"text\" placeholder=\"Ex.: Brasília — DF\" required></div></div><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\">Anno di fondazione</label> <input class=\"form-control\" type=\"number\" min=\"1900\" max=\"2026\" required></div><div class=\"form-field\"> <label class=\"form-label\">Beneficiari al mese (stima)</label> <input class=\"form-control\" type=\"text\" required></div></div><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\">Nome del tutore legale</label><input class=\"form-control\" type=\"text\" required></div><div class=\"form-field\"> <label class=\"form-label\">Posizione</label> <input class=\"form-control\" type=\"text\" required></div></div><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\">E-mail istituzionale</label><input class=\"form-control\" type=\"email\" required></div><div class=\"form-field\"> <label class=\"form-label\">Telefono / WhatsApp</label><input class=\"form-control\" type=\"tel\" required></div></div><div class=\"form-field\"> <label class=\"form-label\">Sito web o social network (se presente)</label><input class=\"form-control\" type=\"url\"></div><div class=\"form-field\"> <label class=\"form-label\">Tipo di supporto di interesse</label><select class=\"form-control\" required><option value=Selecione> Selezionare</option><option value=Financeiro> Finanziario</option><option value=Suprimentos> Forniture</option><option value=Ambos> Entrambi</option><option value=\"A definir\"> Da definire</option></select></div><div class=\"form-field\"> <label class=\"form-label\">Descrizione del lavoro</label> <textarea class=\"form-control\" placeholder=\"Descreva brevemente o que a ONG faz, quem atende e como opera\" required></textarea></div> <label class=\"form-checkbox\"><input type=\"checkbox\" required><span>Ho letto e accetto i criteri di selezione pubblici. Autorizzo Instituto Brasil Te Ama a contattarmi per l&#39;analisi della registrazione.</span></label> <button type=\"submit\" class=\"btn btn--primary btn--lg\" style=\"margin-top: 8px;\">Invia registrazione →</button><p style=\"font-size: 12px; color: var(--text-gray); margin-top: 16px; line-height: 1.6;\"> L&#39;invio di questo modulo non garantisce l&#39;approvazione o il supporto immediati. L&#39;Istituto valuterà la richiesta in base a criteri di ammissibilità pubblici e risponderà entro 15 giorni lavorativi.</p></form></div></div></section>" },
  fr: { title: "Pour les ONG — Instituto Brasil Te Ama", description: "Votre ONG peut bénéficier du soutien du réseau Brasil Te Ama. Les organisations œuvrant auprès des populations vulnérables peuvent s&#39;inscrire selon des critères clairs, avec obligation de rendre des comptes et respect de leur autonomie.", html: "<section class=\"subhero\"><div class=\"container\"><div class=\"subhero__inner fade-up\"><span class=\"eyebrow eyebrow--bordo\">Pour les ONG institutionnelles</span><h1 class=\"subhero__title\"> Votre ONG peut aller plus loin —<br> avec un réseau <em>déjà en mouvement.</em></h1><p class=\"subhero__sub\"> Instituto Brasil Te Ama met en relation des organisations humanitaires vérifiées avec un réseau de soutien structuré, bénéficiant des accréditations de l&#39;Ordre souverain des chevaliers de Malte OSJ, d&#39;entreprises partenaires et d&#39;une transparence à chaque étape.</p><div style=\"margin-top: 28px; display: flex; gap: 14px; flex-wrap: wrap;\"> <a href=\"#formulario\" class=\"btn btn--primary\">Enregistrer mon ONG →</a> <a href=\"#criterios\" class=\"btn btn--secondary\">Comprendre les critères ↓</a></div></div></div></section>\r\n\r\n<!-- O QUE OFERECEMOS --><section class=\"section section--white\"><div class=\"container\"><div class=\"section-header fade-up\"> <span class=\"eyebrow\">Ce que nous proposons</span><h2 class=\"section-title\"> Ce que l&#39;Institut propose<br> pour les ONG.</h2><hr class=\"divider\"><p class=\"section-sub\" style=\"margin-top: 18px;\"> Il ne s&#39;agit pas d&#39;un don ponctuel. Il ne s&#39;agit pas de visibilité pour une campagne. Il s&#39;agit d&#39;un partenariat à long terme, avec des critères clairs, un processus transparent et un engagement mutuel. </p></div><div class=\"grid\" style=\"grid-template-columns: repeat(3, 1fr); gap: 20px;\"><article class=\"card fade-up delay-1\"><div class=\"card__body\" style=\"padding: 28px;\"><div style=\"width:42px; height:42px; border-radius: 10px; background: var(--blush); display: inline-flex; align-items: center; justify-content: center; color: var(--bordo); margin-bottom: 14px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 18px; line-height: 1.3; margin-bottom: 10px;\"> soutien financier ou structurel</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> Les ressources générées par le programme Selo Brasil Te Ama sont destinées aux ONG enregistrées, sous forme d&#39;aide financière ou de fournitures. </p></div></article><article class=\"card fade-up delay-2\"><div class=\"card__body\" style=\"padding: 28px;\"><div style=\"width:42px; height:42px; border-radius: 10px; background: var(--blush); display: inline-flex; align-items: center; justify-content: center; color: var(--bordo); margin-bottom: 14px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 18px; line-height: 1.3; margin-bottom: 10px;\"> Visibilité institutionnelle</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> Les ONG soutenues sont mentionnées dans les communications publiques de l&#39;Institut — sur le site web, dans les rapports et les supports promotionnels — avec discrétion et respect. </p></div></article><article class=\"card fade-up delay-3\"><div class=\"card__body\" style=\"padding: 28px;\"><div style=\"width:42px; height:42px; border-radius: 10px; background: var(--blush); display: inline-flex; align-items: center; justify-content: center; color: var(--bordo); margin-bottom: 14px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 18px; line-height: 1.3; margin-bottom: 10px;\"> Approbation du partenariat</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> L&#39;association avec Instituto Brasil Te Ama et l&#39;Ordre souverain des chevaliers de Malte OSJ confère une crédibilité supplémentaire auprès des donateurs, des partenaires et des organismes publics. </p></div></article><article class=\"card fade-up delay-4\"><div class=\"card__body\" style=\"padding: 28px;\"><div style=\"width:42px; height:42px; border-radius: 10px; background: var(--blush); display: inline-flex; align-items: center; justify-content: center; color: var(--bordo); margin-bottom: 14px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 18px; line-height: 1.3; margin-bottom: 10px;\"> Soutien structuré et continu</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> Il ne s&#39;agit pas d&#39;une action isolée. C&#39;est un flux de soutien généré par les entreprises partenaires de l&#39;Institut. </p></div></article><article class=\"card fade-up delay-1\"><div class=\"card__body\" style=\"padding: 28px;\"><div style=\"width:42px; height:42px; border-radius: 10px; background: var(--blush); display: inline-flex; align-items: center; justify-content: center; color: var(--bordo); margin-bottom: 14px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 18px; line-height: 1.3; margin-bottom: 10px;\"> La transparence à chaque étape.</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> L&#39;Institut documente la destination de chaque subvention. Votre organisation sait ce qu&#39;elle reçoit, quand et d&#39;où cela provient. </p></div></article><article class=\"card fade-up delay-2\"><div class=\"card__body\" style=\"padding: 28px;\"><div style=\"width:42px; height:42px; border-radius: 10px; background: var(--blush); display: inline-flex; align-items: center; justify-content: center; color: var(--bordo); margin-bottom: 14px;\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg></div><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 18px; line-height: 1.3; margin-bottom: 10px;\"> Autonomie préservée</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> Le partenariat se limite au soutien convenu. L’Institut n’intervient pas dans la gestion ni les décisions internes de l’ONG.</p></div></article></div></div></section>\r\n\r\n<!-- COMO FUNCIONA O PROCESSO --><section class=\"section section--alt\" id=\"processo\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Comment ça marche</span><h2 class=\"section-title\"> Comment fonctionne le processus ?<br> sélection d&#39;ONG. </h2><hr class=\"divider divider--center\"></div><div class=\"steps\"><article class=\"step fade-up delay-1\"><div class=\"step__num\"> 01</div><h3 class=\"step__title\"> Registre</h3><p class=\"step__desc\"> Votre ONG remplit le formulaire avec ses données institutionnelles, son domaine d&#39;activité et une description de ses travaux. Aucun document n&#39;est requis à ce stade.</p></article><article class=\"step fade-up delay-2\"><div class=\"step__num\"> 02</div><h3 class=\"step__title\"> Analyse institutionnelle</h3><p class=\"step__desc\"> L&#39;Institut évalue l&#39;inscription selon des critères publics. L&#39;analyse est effectuée par l&#39;équipe interne dans un délai de 15 jours ouvrables.</p></article><article class=\"step fade-up delay-3\"><div class=\"step__num\"> 03</div><h3 class=\"step__title\"> Alignement</h3><p class=\"step__desc\"> Réunion visant à harmoniser les conditions, les domaines d&#39;intervention et les attentes. Les ONG non agréées reçoivent des commentaires et des conseils lorsque cela est possible.</p></article><article class=\"step fade-up delay-4\"><div class=\"step__num\"> 04</div><h3 class=\"step__title\"> Partenariat actif</h3><p class=\"step__desc\"> L’ONG fera désormais partie du réseau et bénéficiera d’un soutien structuré, avec un accord de partenariat signé et un suivi périodique.</p></article></div></div></section>\r\n\r\n<!-- CRITÉRIOS --><section class=\"section section--white\" id=\"criterios\"><div class=\"container\"><div class=\"section-header fade-up\"> <span class=\"eyebrow\">Admissibilité</span><h2 class=\"section-title\"> Quels sont les critères ?<br> sélection.</h2><hr class=\"divider\"><p class=\"section-sub\" style=\"margin-top: 18px;\"> Des critères clairs protègent l&#39;intégrité du réseau — pour les entreprises partenaires, pour le public et pour les organisations qui le composent. </p></div><div class=\"grid\" style=\"grid-template-columns: 1fr 1fr 1fr; gap: 16px;\"><article class=\"card fade-up delay-1\" style=\"padding: 0;\"><div style=\"padding: 18px 24px; background: var(--blush); border-bottom: 1px solid var(--border);\"><p style=\"font-size: 11px; font-weight: 700; letter-spacing: 2.5px; color: var(--bordo); text-transform: uppercase;\"> Critères obligatoires </p></div><ul style=\"list-style: none; padding: 22px 24px; display: flex; flex-direction: column; gap: 12px;\"><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polyline points=\"20 6 9 17 4 12\"/></svg> CNPJ (numéro d&#39;identification fiscale des sociétés brésiliennes) actif et en règle, sans restrictions d&#39;enregistrement importantes. </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polyline points=\"20 6 9 17 4 12\"/></svg> Expérience avérée dans un domaine compatible avec les valeurs de l&#39;Institut. </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polyline points=\"20 6 9 17 4 12\"/></svg> Absence d&#39;antécédents publics d&#39;irrégularités graves ou de détournements de fonds. </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polyline points=\"20 6 9 17 4 12\"/></svg> Ouverture à la reddition de comptes à l&#39;Institut </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--bordo)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polyline points=\"20 6 9 17 4 12\"/></svg> Capacité à recevoir du soutien et à l&#39;utiliser de manière vérifiable. </li></ul></article><article class=\"card fade-up delay-2\" style=\"padding: 0;\"><div style=\"padding: 18px 24px; background: rgba(183,154,99,.12); border-bottom: 1px solid var(--border);\"><p style=\"font-size: 11px; font-weight: 700; letter-spacing: 2.5px; color: var(--dourado); text-transform: uppercase;\"> Ils augmentent la priorité. </p></div><ul style=\"list-style: none; padding: 22px 24px; display: flex; flex-direction: column; gap: 12px;\"><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--dourado)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polygon points=\"12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2\"/></svg> Des résultats constants et une longue durée d&#39;existence. </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--dourado)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polygon points=\"12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2\"/></svg> Présence publique vérifiable — site web, réseaux sociaux ou rapports. </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--dourado)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polygon points=\"12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2\"/></svg> Couverture géographique stratégique ou couverture complémentaire aux ONG déjà soutenues. </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--dourado)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><polygon points=\"12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2\"/></svg> Alignement thématique avec les domaines prioritaires de l&#39;Institut. </li></ul></article><article class=\"card fade-up delay-3\" style=\"padding: 0;\"><div style=\"padding: 18px 24px; background: rgba(0,0,0,.04); border-bottom: 1px solid var(--border);\"><p style=\"font-size: 11px; font-weight: 700; letter-spacing: 2.5px; color: var(--grafite); text-transform: uppercase;\"> Ils empêchent l&#39;approbation. </p></div><ul style=\"list-style: none; padding: 22px 24px; display: flex; flex-direction: column; gap: 12px;\"><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--grafite)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg> CNPJ inactif ou CNPJ présentant une irrégularité grave non résolue. </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--grafite)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg> Antécédents de détournement de fonds ou d&#39;irrégularités institutionnelles documentées. </li><li style=\"display: flex; gap: 10px; align-items: flex-start; font-size: 13px; color: var(--grafite); line-height: 1.5;\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"var(--grafite)\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" style=\"flex-shrink: 0; margin-top: 3px;\"><line x1=\"18\" y1=\"6\" x2=\"6\" y2=\"18\"/><line x1=\"6\" y1=\"6\" x2=\"18\" y2=\"18\"/></svg> Actions incompatibles avec les valeurs de Instituto Brasil Te Ama</li></ul></article></div></div></section>\r\n\r\n<!-- MOOD BAND --><section class=\"section section--white\"><div class=\"container\"><div class=\"mood-band fade-up\"><div class=\"image-slot\" data-slot-id=\"ongs-mood\" data-shape=\"rect\" data-fit=\"cover\" style=\"width:100%;height:auto;aspect-ratio:21/7;;position:relative;overflow:hidden;background:rgba(0,0,0,.04)\"> <span class=\"image-slot__ph\">Image de l&#39;environnement — espoir, mains, communauté, nature</span></div><div class=\"mood-band__overlay\"><div class=\"mood-band__text\"> <span class=\"eyebrow\">Le réseau</span><p class=\"mood-band__quote\"> Un partenariat à long terme — avec des critères clairs.</p></div></div></div></div></section>\r\n\r\n<!-- FRENTES TAGS --><section class=\"section section--alt\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Fronts</span><h2 class=\"section-title\"> Avec quelles causes<br> L&#39;Institut est en activité.</h2><hr class=\"divider divider--center\"><p class=\"section-sub\" style=\"margin-top: 18px;\"> Instituto Brasil Te Ama intervient dans 8 zones d&#39;intervention humanitaire. Les ONG œuvrant dans l&#39;une de ces zones peuvent demander leur enregistrement. </p></div><div style=\"display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; max-width: 880px; margin: 0 auto;\" class=\"fade-up\"> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">Santé,</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">Éducation,</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">Citoyenneté</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">, Sports</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">, Aide sociale,</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">Réinsertion sociale,</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">Droits des femmes</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">, Personnes sans-abri,</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">Soutien aux personnes âgées,</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">Coopération internationale</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">, Environnement</span> <span class=\"chip chip--bordo\" style=\"font-size: 14px; padding: 12px 20px;\">, Autonomisation des femmes</span></div></div></section>\r\n\r\n<!-- O QUE A ONG ASSUME --><section class=\"section section--white\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Engagements</span><h2 class=\"section-title\"> Que suppose l&#39;ONG ?<br> lors de votre inscription. </h2><hr class=\"divider divider--center\"></div><div class=\"grid\" style=\"grid-template-columns: repeat(2, 1fr); gap: 20px; max-width: 920px; margin: 0 auto;\"><article class=\"card fade-up delay-1\"><div class=\"card__body\" style=\"padding: 28px;\"><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 19px; line-height: 1.3; margin-bottom: 10px;\"> Responsabilisation périodique</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> L’ONG s’engage à fournir des informations sur l’utilisation des fonds reçus, selon le format et la fréquence définis dans l’accord de partenariat. </p></div></article><article class=\"card fade-up delay-2\"><div class=\"card__body\" style=\"padding: 28px;\"><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 19px; line-height: 1.3; margin-bottom: 10px;\"> Communication responsable</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> Le nom et la marque Instituto Brasil Te Ama ne peuvent être associés au travail de l&#39;ONG qu&#39;avec une autorisation préalable et selon les conditions définies par l&#39;Institut. </p></div></article><article class=\"card fade-up delay-3\"><div class=\"card__body\" style=\"padding: 28px;\"><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 19px; line-height: 1.3; margin-bottom: 10px;\"> conduite publique compatible</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> L’ONG maintient une conduite publique conforme aux valeurs du réseau — le respect, la transparence et la dignité des personnes qu’elle sert — dans toutes ses communications. </p></div></article><article class=\"card fade-up delay-4\"><div class=\"card__body\" style=\"padding: 28px;\"><h3 style=\"font-family: var(--font-lora); font-weight: 700; font-size: 19px; line-height: 1.3; margin-bottom: 10px;\"> Autonomie préservée</h3><p style=\"font-size: 14px; color: var(--text-gray); line-height: 1.65;\"> L’Institut n’intervient pas dans la gestion ni les décisions internes de l’ONG. Le partenariat se limite au soutien et au suivi des ressources convenus.</p></div></article></div></div></section>\r\n\r\n<!-- FAQ --><section class=\"section section--alt\" id=\"faq\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Foire aux questions</span><h2 class=\"section-title\"> FAQ — ONG </h2><hr class=\"divider divider--center\"></div><div class=\"faq-list fade-up\"><details class=\"faq-item\"><summary> L’inscription garantit-elle que mon ONG recevra du soutien ?</summary><div class=\"faq-item__body\"> Non. Le formulaire d&#39;inscription déclenche une évaluation institutionnelle. Ce n&#39;est qu&#39;après analyse, approbation et signature de la convention de partenariat que l&#39;ONG intègre officiellement le réseau et peut recevoir un financement.</div></details><details class=\"faq-item\"><summary> Quel type de soutien l&#39;Institut propose-t-il ?</summary><div class=\"faq-item__body\"> Le soutien peut être financier, sous forme de fournitures, ou d&#39;une autre nature, selon les besoins de l&#39;ONG et la disponibilité des ressources du programme à chaque cycle.</div></details><details class=\"faq-item\"><summary> L’Institut s’immisce-t-il dans la gestion de mon ONG ?</summary><div class=\"faq-item__body\"> Non. Le partenariat se limite au soutien et au suivi convenus de l’utilisation des ressources. L’Institut préserve l’autonomie et la direction de chaque ONG partenaire.</div></details><details class=\"faq-item\"><summary> Mon ONG a-t-elle besoin de la certification CEBAS pour s&#39;enregistrer ?</summary><div class=\"faq-item__body\"> Ce n&#39;est pas obligatoire. L&#39;Institut évalue la documentation et les performances réelles de l&#39;ONG ; les certifications CEBAS et autres sont prises en compte pour la priorisation, mais ne constituent pas des prérequis absolus.</div></details><details class=\"faq-item\"><summary> Puis-je utiliser le nom de l&#39;Institut dans mes communications après mon inscription ?</summary><div class=\"faq-item__body\"> Non. L’utilisation du nom, de la marque et de tout élément relatif à l’Institut est soumise à autorisation préalable et régie par l’accord de partenariat. L’enregistrement n’autorise aucune utilisation publique.</div></details><details class=\"faq-item\"><summary> Combien de temps faut-il pour recevoir une réponse après l&#39;inscription ?</summary><div class=\"faq-item__body\"> L’Institut répondra dans les 15 jours ouvrables suivant la réception de l’inscription. Les ONG retenues à l’issue de l’évaluation initiale seront invitées à un entretien plus approfondi.</div></details><details class=\"faq-item\"><summary> Comment se déroule le suivi après l&#39;approbation ?</summary><div class=\"faq-item__body\"> Le suivi est défini dans l&#39;accord de partenariat, qui précise la fréquence, les modalités de reddition de comptes et le canal de communication entre l&#39;Institut et l&#39;ONG. L&#39;Institut n&#39;intervient pas dans le fonctionnement, mais contrôle l&#39;utilisation des ressources.</div></details></div></div></section>\r\n\r\n<!-- FORMULÁRIO --><section class=\"section section--white\" id=\"formulario\"><div class=\"container\"><div class=\"section-header section-header--center fade-up\"> <span class=\"eyebrow\">Registre</span><h2 class=\"section-title\"> Enregistrez votre ONG —<br> Le processus commence ici.</h2><hr class=\"divider divider--center\"><p class=\"section-sub\" style=\"margin-top: 18px;\"> Veuillez compléter les informations ci-dessous. L’inscription ne garantit pas une assistance immédiate ; elle marque le début d’une évaluation institutionnelle. Notre équipe vous recontactera sous 15 jours ouvrables. </p></div><div class=\"form-card fade-up\" style=\"max-width: 880px; margin: 0 auto;\"><form><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\">Nom de l&#39;ONG</label><input class=\"form-control\" type=\"text\" required></div><div class=\"form-field\"> <label class=\"form-label\">CNPJ</label> <input class=\"form-control\" type=\"text\" placeholder=\"00.000.000/0000-00\" required></div></div><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\">Principal domaine d&#39;expertise</label><select class=\"form-control\" required><option value=Selecione> Sélectionner</option><option value=\"Saúde\"> Santé</option><option value=\"Educação\"> Éducation</option><option value=Cidadania> Citoyenneté</option><option value=\"Direitos humanos\"> droits de l&#39;homme</option><option value=\"Empoderamento feminino\"> L&#39;autonomisation des femmes</option><option value=\"Pessoas em situação de rua\"> les sans-abri</option><option value=\"Terceira idade\"> personnes agées</option><option value=Esporte> Sport</option><option value=\"Meio ambiente\"> Environnement</option><option value=Outra> Autre</option></select></div><div class=\"form-field\"> <label class=\"form-label\">État et ville d&#39;opération</label> <input class=\"form-control\" type=\"text\" placeholder=\"Ex.: Brasília — DF\" required></div></div><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\">Année de fondation</label> <input class=\"form-control\" type=\"number\" min=\"1900\" max=\"2026\" required></div><div class=\"form-field\"> <label class=\"form-label\">Bénéficiaires/mois (estimation)</label> <input class=\"form-control\" type=\"text\" required></div></div><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\">Nom du tuteur légal</label><input class=\"form-control\" type=\"text\" required></div><div class=\"form-field\"> <label class=\"form-label\">Position</label> <input class=\"form-control\" type=\"text\" required></div></div><div class=\"form-row\"><div class=\"form-field\"> <label class=\"form-label\">Courriel institutionnel</label><input class=\"form-control\" type=\"email\" required></div><div class=\"form-field\"> <label class=\"form-label\">Téléphone / WhatsApp</label><input class=\"form-control\" type=\"tel\" required></div></div><div class=\"form-field\"> <label class=\"form-label\">Site web ou réseau social (le cas échéant)</label><input class=\"form-control\" type=\"url\"></div><div class=\"form-field\"> <label class=\"form-label\">Type de soutien d&#39;intérêt</label><select class=\"form-control\" required><option value=Selecione> Sélectionner</option><option value=Financeiro> Financier</option><option value=Suprimentos> Fournitures</option><option value=Ambos> Les deux</option><option value=\"A definir\"> À définir</option></select></div><div class=\"form-field\"> <label class=\"form-label\">Description de l&#39;emploi</label> <textarea class=\"form-control\" placeholder=\"Descreva brevemente o que a ONG faz, quem atende e como opera\" required></textarea></div> <label class=\"form-checkbox\"><input type=\"checkbox\" required><span>J&#39;ai lu et j&#39;accepte les critères de sélection publics. J&#39;autorise Instituto Brasil Te Ama à me contacter pour l&#39;analyse de mon inscription.</span></label> <button type=\"submit\" class=\"btn btn--primary btn--lg\" style=\"margin-top: 8px;\">Soumettre l&#39;inscription →</button><p style=\"font-size: 12px; color: var(--text-gray); margin-top: 16px; line-height: 1.6;\"> L’envoi de ce formulaire ne garantit pas une approbation ou un soutien immédiat. L’Institut évaluera la demande selon les critères d’admissibilité publics et répondra dans un délai de 15 jours ouvrables.</p></form></div></div></section>" },
};
export default t;
